) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `stock` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` mediumint(8) unsigned NOT NULL,
  `eol` date DEFAULT NULL,
  `location` varchar(255) NOT NULL,
  `in_price` decimal(10,2) NOT NULL,
  `cat_price` decimal(10,2) DEFAULT NULL COMMENT 'cat price manual',
  `lotnr` varchar(255) NOT NULL,
  `volume` decimal(10,2) NOT NULL,
  `barcode` varchar(255) NOT NULL,
  `supplier` varchar(255) DEFAULT NULL,
  `verify` datetime DEFAULT NULL,
  `state` tinyint(3) unsigned NOT NULL,
  `info` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `gsl_lookup` (`eol`,`location`,`lotnr`),
  KEY `barcode` (`barcode`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `stock_input` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user` int(11) NOT NULL,
  `location` int(11) NOT NULL,
  `msg` text NOT NULL,
  `updated_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `stock_limit` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
